/** Native Git refresh acceptance; filesystem repositories and HTTP credential are synthetic. */
import assert from 'node:assert/strict'
import { execFile } from 'node:child_process'
import { chmod, cp, mkdir, readFile, rm, symlink, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { promisify } from 'node:util'
import type { ToolExecutionResult } from '@deepseek-ai/dsh-tools'
import type { gitHttpFixture } from './git-http.ts'

export async function checkFetch(
  root: string, workspace: string, remote: Awaited<ReturnType<typeof gitHttpFixture>>,
  call: (name: string, args: Record<string, unknown>, signal?: AbortSignal) => Promise<ToolExecutionResult>,
): Promise<void> {
  const gitAt = async (path: string, ...args: string[]) => (await promisify(execFile)('git', ['-C', path, ...args])).stdout.trim()
  const git = (...args: string[]) => gitAt(workspace, ...args)
  const source = await readFile(join(workspace, 'source.txt'))
  const index = await readFile(join(workspace, '.git/index'))
  const upstream = join(root, 'upstream')
  await promisify(execFile)('git', ['clone', remote.bare, upstream])
  await gitAt(upstream, 'config', 'user.name', 'Fixture')
  await gitAt(upstream, 'config', 'user.email', 'fixture@example.invalid')
  const initialRemote = await gitAt(upstream, 'rev-parse', 'HEAD')
  await writeFile(join(upstream, 'upstream.txt'), 'first remote advance\n')
  await gitAt(upstream, 'add', 'upstream.txt')
  await gitAt(upstream, 'commit', '-m', 'remote advance')
  const first = await gitAt(upstream, 'rev-parse', 'HEAD')
  await gitAt(upstream, 'branch', 'future')
  await gitAt(upstream, 'push', 'origin', 'codex/fixture', 'future')
  try {
    await writeFile(join(workspace, 'source.txt'), 'staged local work\n')
    await git('add', 'source.txt')
    await writeFile(join(workspace, 'source.txt'), 'staged local work\nunfinished local work\n')
    await writeFile(join(workspace, 'untracked.txt'), 'untracked local work\n')
    await writeFile(join(workspace, '.git/FETCH_HEAD'), 'preserved fetch head sentinel\n')
    const head = await git('rev-parse', 'HEAD')
    const localBranches = await git('for-each-ref', '--format=%(refname) %(objectname)', 'refs/heads/')
    const dirtyIndex = await readFile(join(workspace, '.git/index'))
    const dirtySource = await readFile(join(workspace, 'source.txt'))
    const refreshed = await call('forge_fetch', {})
    assert(!refreshed.isError, JSON.stringify(refreshed))
    assert.equal(await git('rev-parse', 'refs/remotes/origin/codex/fixture'), first)
    assert.equal(await git('rev-parse', 'refs/remotes/origin/future'), first)
    assert.equal(await git('rev-parse', 'HEAD'), head)
    assert.equal(await git('for-each-ref', '--format=%(refname) %(objectname)', 'refs/heads/'), localBranches)
    assert.deepEqual(await readFile(join(workspace, '.git/index')), dirtyIndex)
    assert.deepEqual(await readFile(join(workspace, 'source.txt')), dirtySource)
    assert.equal(await readFile(join(workspace, 'untracked.txt'), 'utf8'), 'untracked local work\n')
    assert.equal(await readFile(join(workspace, '.git/FETCH_HEAD'), 'utf8'), 'preserved fetch head sentinel\n')
    assert(!JSON.stringify(refreshed).includes('synthetic-forgejo-token'))
    await gitAt(remote.bare, 'update-ref', '-d', 'refs/heads/future')
    assert(!(await call('forge_fetch', {})).isError)
    assert.equal(await git('rev-parse', 'refs/remotes/origin/future'), first, 'no pruning')
    await writeFile(join(upstream, 'upstream.txt'), 'second remote advance\n')
    await gitAt(upstream, 'commit', '-am', 'second remote advance')
    await gitAt(upstream, 'push', 'origin', 'codex/fixture')
    const second = await gitAt(upstream, 'rev-parse', 'HEAD')
    assert(!(await call('forge_fetch', {})).isError)
    assert.equal(await git('rev-parse', 'refs/remotes/origin/codex/fixture'), second)
    await gitAt(remote.bare, 'update-ref', 'refs/heads/codex/fixture', initialRemote)
    await gitAt(remote.bare, 'update-ref', 'refs/heads/new-after-rewind', first)
    const diverged = await call('forge_fetch', {})
    assert(diverged.isError)
    assert.match(JSON.stringify(diverged), /diverged; no tracking refs were updated/)
    assert.equal(await git('rev-parse', 'refs/remotes/origin/codex/fixture'), second)
    assert.equal(await git('for-each-ref', '--format=%(refname)', 'refs/remotes/origin/new-after-rewind'), '')
    await gitAt(remote.bare, 'update-ref', 'refs/heads/codex/fixture', second)
    // Tracking metadata must not redirect writes into local branches or dirty files.
    const tracking = 'refs/remotes/origin/codex/fixture'
    await git('symbolic-ref', tracking, 'refs/heads/codex/fixture')
    const symbolic = await call('forge_fetch', {})
    assert(symbolic.isError)
    assert.match(JSON.stringify(symbolic), /Symbolic tracking refs/)
    assert.equal(await git('rev-parse', 'HEAD'), head)
    await git('update-ref', '--no-deref', tracking, second)
    const log = join(workspace, '.git/logs', tracking)
    const originalLog = await readFile(log).catch(() => undefined)
    await mkdir(dirname(log), { recursive: true })
    await rm(log, { force: true })
    await symlink(join(workspace, 'source.txt'), log)
    const aliased = await call('forge_fetch', {})
    assert(aliased.isError)
    assert.match(JSON.stringify(aliased), /metadata aliases/)
    assert.deepEqual(await readFile(join(workspace, 'source.txt')), dirtySource)
    await rm(log)
    if (originalLog) await writeFile(log, originalLog)
    // A fresh object prevents Git's already-present-object shortcut from skipping transport.
    await writeFile(join(upstream, 'upstream.txt'), 'new object for source-helper check\n')
    await gitAt(upstream, 'commit', '-am', 'new object for confined import')
    await gitAt(upstream, 'push', 'origin', 'codex/fixture')
    // Source-configured transport helpers must never execute during object import.
    const helper = join(workspace, 'synthetic-fetch-helper')
    await writeFile(helper, `#!/bin/sh\nif (exec 3< '${join(root, 'private/.credentials.yaml')}') 2>/dev/null; then printf escaped; else printf confined; fi > '${join(workspace, 'fetch-helper-result')}'\nexit 1\n`)
    await chmod(helper, 0o755)
    const section = `url.ext::${helper} `
    await git('config', `${section}.insteadOf`, '/workspaces')
    await git('config', 'protocol.ext.allow', 'always')
    const malicious = await call('forge_fetch', {})
    assert(!malicious.isError, JSON.stringify(malicious))
    await assert.rejects(readFile(join(workspace, 'fetch-helper-result')), { code: 'ENOENT' })
    assert.equal(await git('rev-parse', tracking), await gitAt(upstream, 'rev-parse', 'HEAD'))
    assert.equal(await git('rev-parse', 'HEAD'), head)
    assert.deepEqual(await readFile(join(workspace, '.git/index')), dirtyIndex)
    assert.deepEqual(await readFile(join(workspace, 'source.txt')), dirtySource)
    await git('config', '--remove-section', section)
    await git('config', '--unset', 'protocol.ext.allow')
    await gitAt(remote.bare, 'update-ref', 'refs/heads/codex/fixture', second)
    await git('update-ref', tracking, second)
    const shared = join(workspace, 'synthetic-shared-git')
    await cp(join(workspace, '.git'), shared, { recursive: true })
    await writeFile(join(workspace, '.git/commondir'), '../synthetic-shared-git\n')
    const sharedMetadata = await call('forge_fetch', {})
    assert(sharedMetadata.isError)
    assert.match(JSON.stringify(sharedMetadata), /Shared Git metadata/)
    await rm(join(workspace, '.git/commondir'))
    await rm(shared, { recursive: true })
    const requestCount = remote.requestCount()
    await git('remote', 'set-url', 'origin', `${remote.origin}/other/repository.git`)
    assert((await call('forge_fetch', {})).isError)
    assert.equal(remote.requestCount(), requestCount, 'wrong origin must be rejected before credentialed transport')
    await git('remote', 'set-url', 'origin', `${remote.origin}/apps/atlas.git`)
    assert((await call('forge_fetch', { force: true })).isError)
    remote.delay(5_000)
    const cancellation = new AbortController()
    const beforeCancellation = remote.requestCount()
    const pending = call('forge_fetch', {}, cancellation.signal)
    const waitUntil = Date.now() + 5_000
    while (remote.requestCount() === beforeCancellation && Date.now() < waitUntil) await new Promise(resolve => setTimeout(resolve, 10))
    assert(remote.requestCount() > beforeCancellation, 'credentialed fetch must reach the synthetic server before cancellation')
    cancellation.abort()
    assert((await pending).isError)
    remote.delay(0)
    assert.equal(await git('rev-parse', 'HEAD'), head)
    assert.deepEqual(await readFile(join(workspace, '.git/index')), dirtyIndex)
    assert.deepEqual(await readFile(join(workspace, 'source.txt')), dirtySource)
  } finally {
    remote.delay(0)
    await writeFile(join(workspace, 'source.txt'), source)
    await writeFile(join(workspace, '.git/index'), index)
  }
}
